        try thumbnailData.write(to: fileURL(for: bookID, size: .thumbnail), options: .atomic)
    }

    /// Читает и сразу декодирует картинку, чтобы главный поток не тратил на это время при прокрутке.
    @concurrent
    static func loadImage(for bookID: UUID, size: CoverSize) async -> UIImage? {
        let path = fileURL(for: bookID, size: size).path(percentEncoded: false)
        guard let image = UIImage(contentsOfFile: path) else { return nil }
        return image.preparingForDisplay() ?? image
    }

    @concurrent
    static func removeCover(for bookID: UUID) async {
        for size in CoverSize.allCases {
            try? FileManager.default.removeItem(at: fileURL(for: bookID, size: size))
        }
    }

    /// Удаляет файлы книг, которых больше нет или у которых обложку убрали.
    /// Свежие файлы (моложе 10 минут) не трогает, чтобы не задеть обложку, которая сохраняется прямо сейчас.
    @concurrent
    static func removeOrphans(keeping bookIDs: Set<UUID>) async {
        let fileManager = FileManager.default
        guard let files = try? fileManager.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: [.contentModificationDateKey]
        ) else { return }

        let freshnessLimit = Date.now.addingTimeInterval(-10 * 60)
        for file in files {
            let idPrefix = String(file.lastPathComponent.prefix(36))
            if let id = UUID(uuidString: idPrefix), bookIDs.contains(id) { continue }
            let modified = (try? file.resourceValues(forKeys: [.contentModificationDateKey]))?
                .contentModificationDate ?? .distantPast
            guard modified < freshnessLimit else { continue }
            try? fileManager.removeItem(at: file)
        }
    }

    /// Перерисовка заодно поворачивает снимок правильно: камера отдаёт его с пометкой ориентации.
    private static func resized(_ image: UIImage, maxPixelLength: CGFloat) -> UIImage {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        let factor = min(1, maxPixelLength / max(pixelWidth, pixelHeight))
        let target = CGSize(width: (pixelWidth * factor).rounded(), height: (pixelHeight * factor).rounded())

        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: target, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }

    /// HEIC примерно вдвое меньше JPEG при том же качестве; JPEG — запасной вариант.
    private static func encoded(_ image: UIImage) -> Data? {
        if let cgImage = image.cgImage {
            let data = NSMutableData()
            if let destination = CGImageDestinationCreateWithData(
                data, UTType.heic.identifier as CFString, 1, nil
            ) {
                let options = [kCGImageDestinationLossyCompressionQuality: 0.75] as CFDictionary
                CGImageDestinationAddImage(destination, cgImage, options)
                if CGImageDestinationFinalize(destination) {
                    return data as Data
                }
            }
        }
        return image.jpegData(compressionQuality: 0.8)
    }
}
```

### CoverImage.swift: показ обложки с кэшем

```swift
import SwiftUI
import UIKit

nonisolated struct CoverKey: Hashable, Sendable {
    let bookID: UUID
    let version: Date
    let size: CoverSize

    var cacheKey: String {
        "\(bookID.uuidString)-\(size.rawValue)-\(version.timeIntervalSinceReferenceDate)"
    }
}

/// Декодированные картинки в памяти. NSCache сам потокобезопасен и сам освобождается при нехватке памяти.
nonisolated final class CoverCache: @unchecked Sendable {
    static let shared = CoverCache()

    private let cache = NSCache<NSString, UIImage>()

    private init() {
        cache.totalCostLimit = 50 * 1024 * 1024
    }

    func image(for key: CoverKey) -> UIImage? {
        cache.object(forKey: key.cacheKey as NSString)
    }

    func insert(_ image: UIImage, for key: CoverKey) {
        let pixels = image.size.width * image.scale * image.size.height * image.scale
        cache.setObject(image, forKey: key.cacheKey as NSString, cost: Int(pixels) * 4)
    }
}

struct CoverImage: View {
    let bookID: UUID
    /// `Book.coverUpdatedAt`: при смене обложки меняется ключ, и картинка перезагружается.
    let version: Date?
    let size: CoverSize
    let contentMode: ContentMode

    @State private var loaded: LoadedCover?

    private struct LoadedCover {
        let key: CoverKey
        let image: UIImage
    }

    private var key: CoverKey? {
        version.map { CoverKey(bookID: bookID, version: $0, size: size) }
    }

    private var image: UIImage? {
        guard let key else { return nil }
        if let loaded, loaded.key == key { return loaded.image }
        if let cached = CoverCache.shared.image(for: key) { return cached }
        // Пока грузится большая картинка, показываем миниатюру, если она уже в памяти.
        guard size == .full else { return nil }
        return CoverCache.shared.image(for: CoverKey(bookID: bookID, version: key.version, size: .thumbnail))
    }

    var body: some View {
        Group {
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .aspectRatio(contentMode: contentMode)
            } else {
                Rectangle()
                    .fill(.quaternary)
                    .aspectRatio(2.0 / 3.0, contentMode: .fit)
                    .overlay {
                        Image(systemName: "book.closed")
                            .font(size == .thumbnail ? .body : .largeTitle)
                            .foregroundStyle(.secondary)
                    }
            }
        }
        .task(id: key) {
            await load()
        }
    }

    private func load() async {
        guard let key else {
            loaded = nil
            return
        }
        if let cached = CoverCache.shared.image(for: key) {
            loaded = LoadedCover(key: key, image: cached)
            return
        }
        guard let image = await CoverStore.loadImage(for: key.bookID, size: key.size) else { return }
        CoverCache.shared.insert(image, for: key)
        guard !Task.isCancelled else { return }
        loaded = LoadedCover(key: key, image: image)
    }
}
```

