```swift
import SwiftData
import SwiftUI

struct BookCoverSection: View {
    let book: Book

    @Environment(\.modelContext) private var modelContext
    @State private var isShowingCamera = false
    @State private var isSaving = false
    @State private var isConfirmingRemoval = false
    @State private var isShowingError = false

    private var hasCover: Bool { book.coverUpdatedAt != nil }

    var body: some View {
        VStack(spacing: 12) {
            CoverImage(bookID: book.id, version: book.coverUpdatedAt, size: .full, contentMode: .fit)
                .frame(maxWidth: 240, maxHeight: 360)
                .clipShape(.rect(cornerRadius: 8))
                .shadow(color: .black.opacity(0.15), radius: 6, y: 3)
                .overlay {
                    if isSaving {
                        ProgressView()
                            .padding()
                            .background(.regularMaterial, in: .rect(cornerRadius: 8))
                    }
                }
                .accessibilityLabel(hasCover ? "Обложка книги" : "Обложки пока нет")

            HStack {
                if CameraPicker.isAvailable {
                    Button(hasCover ? "Переснять" : "Сфотографировать обложку", systemImage: "camera") {
                        isShowingCamera = true
                    }
                }
                if hasCover {
                    Button("Удалить", systemImage: "trash", role: .destructive) {
                        isConfirmingRemoval = true
                    }
                }
            }
            .buttonStyle(.bordered)
            .disabled(isSaving)
        }
        .fullScreenCover(isPresented: $isShowingCamera) {
            CameraPicker { photo in
                isShowingCamera = false
                if let photo {
                    Task { await saveCover(photo) }
                }
            }
            .ignoresSafeArea()
        }
        .confirmationDialog("Удалить обложку?", isPresented: $isConfirmingRemoval, titleVisibility: .visible) {
            Button("Удалить обложку", role: .destructive) {
                Task { await removeCover() }
            }
        }
        .alert("Не удалось сохранить обложку", isPresented: $isShowingError) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Попробуйте ещё раз. Если не получится, проверьте, есть ли свободное место на iPhone.")
        }
    }

    private func saveCover(_ photo: UIImage) async {
        isSaving = true
        defer { isSaving = false }
        do {
            try await CoverStore.save(photo, for: book.id)
            book.coverUpdatedAt = .now
            try? modelContext.save()
        } catch {
            isShowingError = true
        }
    }

    private func removeCover() async {
        let bookID = book.id
        book.coverUpdatedAt = nil
        try? modelContext.save()
        await CoverStore.removeCover(for: bookID)
    }
}
