## 2. `CoverStore.swift`: хранение и обработка фото

```swift
import UIKit

/// Хранит обложки файлами на диске: большая версия для экрана книги и маленькая для списка.
/// Это actor: вся тяжёлая работа (уменьшение 12 Мп фото, запись, чтение) идёт не на главном потоке.
actor CoverStore {
    static let shared = CoverStore()

    /// Большая версия: хватает для чёткой картинки на экране книги.
    private let fullMaxSide: CGFloat = 1200
    /// Маленькая версия: строка списка 48×72 pt на экране @3x.
    private let thumbnailMaxSide: CGFloat = 240
    private let jpegQuality: CGFloat = 0.8
    private let directory: URL

    init() {
        let dir = URL.applicationSupportDirectory.appending(path: "Covers", directoryHint: .isDirectory)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        directory = dir
    }

    /// Уменьшает фото, сохраняет две версии и возвращает новый coverID.
    func saveCover(from photo: UIImage) throws -> UUID {
        let id = UUID()
        let full = resized(photo, maxSide: fullMaxSide)
        let thumbnail = resized(full, maxSide: thumbnailMaxSide)
        guard let fullData = full.jpegData(compressionQuality: jpegQuality),
              let thumbnailData = thumbnail.jpegData(compressionQuality: jpegQuality)
        else { throw CocoaError(.fileWriteUnknown) }

        do {
            try fullData.write(to: fileURL(id, suffix: ""), options: .atomic)
            try thumbnailData.write(to: fileURL(id, suffix: "-thumb"), options: .atomic)
        } catch {
            deleteCover(id)
            throw error
        }
        return id
    }

    func thumbnail(for id: UUID) -> UIImage? {
        loadImage(at: fileURL(id, suffix: "-thumb"))
    }

    func fullImage(for id: UUID) -> UIImage? {
        loadImage(at: fileURL(id, suffix: ""))
    }

    func deleteCover(_ id: UUID) {
        try? FileManager.default.removeItem(at: fileURL(id, suffix: ""))
        try? FileManager.default.removeItem(at: fileURL(id, suffix: "-thumb"))
    }

    /// Удаляет файлы, на которые не ссылается ни одна книга (например, книгу удалили,
    /// а приложение закрылось раньше, чем стёрлись файлы). Свежие файлы не трогает:
    /// они могут принадлежать обложке, которая прямо сейчас сохраняется.
    func removeOrphans(keeping liveIDs: Set<UUID>) {
        let fileManager = FileManager.default
        guard let files = try? fileManager.contentsOfDirectory(
            at: directory, includingPropertiesForKeys: [.contentModificationDateKey]
        ) else { return }

        let cutoff = Date.now.addingTimeInterval(-60 * 60)
        for file in files {
            let name = file.deletingPathExtension().lastPathComponent
                .replacingOccurrences(of: "-thumb", with: "")
            guard let id = UUID(uuidString: name), !liveIDs.contains(id) else { continue }
            let modified = (try? file.resourceValues(forKeys: [.contentModificationDateKey]))?
                .contentModificationDate ?? .distantPast
            if modified < cutoff {
                try? fileManager.removeItem(at: file)
            }
        }
    }

    // MARK: - Private

    private func fileURL(_ id: UUID, suffix: String) -> URL {
        directory.appending(path: "\(id.uuidString)\(suffix).jpg", directoryHint: .notDirectory)
    }

    private func loadImage(at url: URL) -> UIImage? {
        guard let image = UIImage(contentsOfFile: url.path(percentEncoded: false)) else { return nil }
        // Раскодировать картинку здесь, а не при первом показе на главном потоке.
        return image.preparingForDisplay() ?? image
    }

    /// Уменьшает так, чтобы длинная сторона была не больше maxSide пикселей.
    /// Поворот фото с камеры учитывается: результат всегда «стоит прямо».
    private func resized(_ image: UIImage, maxSide: CGFloat) -> UIImage {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        let factor = min(1, maxSide / max(pixelWidth, pixelHeight))
        let target = CGSize(width: (pixelWidth * factor).rounded(), height: (pixelHeight * factor).rounded())

        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: target, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }
}

/// Маленькие обложки, которые уже показывались: при прокрутке назад они появляются мгновенно.
/// Объём ограничен (~40 МБ), при нехватке памяти система сама его очищает.
@MainActor
final class CoverThumbnailCache {
    static let shared = CoverThumbnailCache()
    private let cache = NSCache<NSUUID, UIImage>()

    private init() {
        cache.totalCostLimit = 40 * 1024 * 1024
    }

    func image(for id: UUID) -> UIImage? {
        cache.object(forKey: id as NSUUID)
    }

    func insert(_ image: UIImage, for id: UUID) {
        let bytes = Int(image.size.width * image.scale * image.size.height * image.scale) * 4
        cache.setObject(image, forKey: id as NSUUID, cost: bytes)
    }

    func remove(_ id: UUID) {
        cache.removeObject(forKey: id as NSUUID)
    }
}
```

## 3. `CoverViews.swift`: как обложка выглядит

```swift
import SwiftUI

/// Заглушка для книги без обложки.
struct CoverPlaceholder: View {
    var body: some View {
        Rectangle()
            .fill(.quaternary)
            .overlay {
                Image(systemName: "book.closed")
                    .foregroundStyle(.secondary)
            }
    }
}

/// Маленькая обложка для строки списка.
struct CoverThumbnail: View {
    let coverID: UUID?
    @State private var loaded: (id: UUID, image: UIImage)?

    private var image: UIImage? {
        guard let coverID else { return nil }
        if let loaded, loaded.id == coverID { return loaded.image }
        return CoverThumbnailCache.shared.image(for: coverID)
    }

    var body: some View {
        CoverPlaceholder()
            .frame(width: 48, height: 72)
            .overlay {
                if let image {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFill()
                }
            }
            .clipShape(RoundedRectangle(cornerRadius: 4))
            .accessibilityHidden(true)
            .task(id: coverID) {
                guard let coverID, image == nil else { return }
                if let thumbnail = await CoverStore.shared.thumbnail(for: coverID) {
                    CoverThumbnailCache.shared.insert(thumbnail, for: coverID)
                    loaded = (coverID, thumbnail)
                }
            }
    }
}

/// Большая обложка для экрана книги. Пока грузится большая версия, показывает маленькую.
struct CoverLarge: View {
    let coverID: UUID?
    @State private var loaded: (id: UUID, image: UIImage)?

    private var image: UIImage? {
        guard let coverID else { return nil }
        if let loaded, loaded.id == coverID { return loaded.image }
        return CoverThumbnailCache.shared.image(for: coverID)
    }

    var body: some View {
        Group {
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
            } else {
                CoverPlaceholder()
                    .aspectRatio(2 / 3, contentMode: .fit)
            }
        }
        .frame(maxWidth: 220, maxHeight: 330)
        .clipShape(RoundedRectangle(cornerRadius: 8))
        .shadow(color: .black.opacity(0.15), radius: 6, y: 3)
        .accessibilityElement()
        .accessibilityLabel(coverID == nil ? "Нет обложки" : "Обложка книги")
        .task(id: coverID) {
            guard let coverID else { return }
            if let full = await CoverStore.shared.fullImage(for: coverID) {
                loaded = (coverID, full)
            }
        }
    }
}
