    private func deleteBook(_ book: Book) {
        let coverID = book.coverID
        modelContext.delete(book)
        try? modelContext.save()
        if let coverID {
            CoverThumbnailCache.shared.remove(coverID)
            Task { await CoverStore.shared.deleteCover(coverID) }
        }
    }

    private func removeOrphanCovers() async {
        let descriptor = FetchDescriptor<Book>(predicate: #Predicate { $0.coverID != nil })
        guard let booksWithCovers = try? modelContext.fetch(descriptor) else { return }
        let liveIDs = Set(booksWithCovers.compactMap(\.coverID))
        await CoverStore.shared.removeOrphans(keeping: liveIDs)
    }
}

