## 6. `BookDetailView.swift`: экран книги

```swift
import SwiftUI
import SwiftData
import AVFoundation

struct BookDetailView: View {
    let book: Book

    @Environment(\.modelContext) private var modelContext
    @Environment(\.openURL) private var openURL

    @State private var showCamera = false
    @State private var showCameraDeniedAlert = false
    @State private var showDeleteConfirmation = false
    @State private var isSavingCover = false
    @State private var errorMessage: String?

    private var cameraAvailable: Bool {
        UIImagePickerController.isSourceTypeAvailable(.camera)
    }

    var body: some View {
        ScrollView {
            VStack(spacing: 16) {
                CoverLarge(coverID: book.coverID)
                    .overlay {
                        if isSavingCover {
                            ProgressView()
                                .controlSize(.large)
                                .padding()
                                .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 12))
                        }
                    }

                coverButtons

                VStack(spacing: 4) {
                    Text(book.title)
                        .font(.title2.bold())
                        .multilineTextAlignment(.center)
                    Text(book.author)
                        .foregroundStyle(.secondary)
                }
            }
            .padding()
            .frame(maxWidth: .infinity)
        }
        .navigationTitle(book.title)
        .navigationBarTitleDisplayMode(.inline)
        .fullScreenCover(isPresented: $showCamera) {
            CameraPicker { photo in
                showCamera = false
                if let photo {
                    Task { await setCover(photo) }
                }
            }
            .ignoresSafeArea()
        }
        .confirmationDialog("Удалить обложку?", isPresented: $showDeleteConfirmation, titleVisibility: .visible) {
            Button("Удалить обложку", role: .destructive) {
                Task { await removeCover() }
            }
        }
        .alert("Нет доступа к камере", isPresented: $showCameraDeniedAlert) {
            Button("Открыть Настройки") {
                if let url = URL(string: UIApplication.openSettingsURLString) {
                    openURL(url)
                }
            }
            Button("Отмена", role: .cancel) {}
        } message: {
            Text("Разрешите доступ к камере в Настройках, чтобы сфотографировать обложку.")
        }
        .alert(
            "Не получилось",
            isPresented: Binding(get: { errorMessage != nil }, set: { if !$0 { errorMessage = nil } })
        ) {
            Button("OK", role: .cancel) {}
        } message: {
            Text(errorMessage ?? "")
        }
    }

    @ViewBuilder
    private var coverButtons: some View {
        HStack {
            if cameraAvailable {
                Button(
                    book.coverID == nil ? "Сфотографировать обложку" : "Переснять",
                    systemImage: "camera"
                ) {
                    openCamera()
                }
            }
            if book.coverID != nil {
                Button("Удалить", systemImage: "trash", role: .destructive) {
                    showDeleteConfirmation = true
                }
            }
        }
        .buttonStyle(.bordered)
        .disabled(isSavingCover)
    }

    private func openCamera() {
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .denied, .restricted:
            showCameraDeniedAlert = true
        default:
            // При первом запуске система сама спросит разрешение.
            showCamera = true
        }
    }

    private func setCover(_ photo: UIImage) async {
        guard !isSavingCover else { return }
        isSavingCover = true
        defer { isSavingCover = false }

        let newID: UUID
        do {
            newID = try await CoverStore.shared.saveCover(from: photo)
        } catch {
            errorMessage = "Не удалось сохранить фото. Возможно, на телефоне мало свободного места."
            return
        }

        // Книгу могли удалить, пока фото обрабатывалось.
        guard book.modelContext != nil, !book.isDeleted else {
            await CoverStore.shared.deleteCover(newID)
            return
        }

        let oldID = book.coverID
        book.coverID = newID
        do {
            try modelContext.save()
        } catch {
            book.coverID = oldID
            await CoverStore.shared.deleteCover(newID)
            errorMessage = "Не удалось сохранить обложку. Попробуйте ещё раз."
            return
        }

        if let oldID {
            CoverThumbnailCache.shared.remove(oldID)
            await CoverStore.shared.deleteCover(oldID)
        }
    }

    private func removeCover() async {
        guard let oldID = book.coverID else { return }
        book.coverID = nil
        do {
            try modelContext.save()
        } catch {
            book.coverID = oldID
            errorMessage = "Не удалось удалить обложку. Попробуйте ещё раз."
            return
        }
        CoverThumbnailCache.shared.remove(oldID)
        await CoverStore.shared.deleteCover(oldID)
    }
}
```

## 7. Настройка проекта (обязательно)

В Info.plist (Xcode → цель приложения → вкладка Info) нужно добавить ключ **Privacy – Camera Usage Description** (`NSCameraUsageDescription`) со значением, например, «Чтобы сфотографировать обложку книги». Без него приложение закроется при открытии камеры.

---

## Ключевые решения

- **Фото уменьшается сразу.** Оригинал с камеры весит 3–5 МБ, а в памяти занимает около 48 МБ. 500 таких фото забили бы телефон и тормозили бы список. Поэтому остаются две версии: большая для экрана книги (длинная сторона 1200 px, ~150 КБ) и маленькая для списка (240 px, ~20 КБ). На 500 книг выйдет примерно 85 МБ на диске.
- **Фото лежат отдельными файлами, в базе только ссылка на них.** Так список из 500 книг открывается так же быстро, как без обложек. Обложки подгружаются в фоне только для строк, которые видны на экране, и запоминаются, поэтому при прокрутке назад появляются сразу.
- **При замене фото меняется имя файла.** Старая картинка не может «застрять» на экране, а старый файл удаляется.
- **Защита от лишних файлов.** Если фото сохранено, а приложение закрылось раньше, чем обновилась книга (или наоборот при удалении), при открытии библиотеки ненужные файлы удаляются. Свежие файлы не старше часа не трогаются.
- **Фото хранятся надёжно.** Папка не очищается системой и попадает в резервную копию iPhone.
- **Обрезка.** В списке обложка обрезается по центру до книжной пропорции 2:3. На экране книги фото показывается целиком.
- **Код рассчитан на разные настройки Swift 6.** Он учитывает и вариант, когда новые проекты Xcode по умолчанию выполняют код на главном потоке.

## Допущения

1. Синхронизации через iCloud пока нет: обложки хранятся только на устройстве и в его резервной копии. Если синхронизация появится, обложки придётся переносить, это отдельная задача.
2. У книги одна обложка. Ручной обрезки и выбора из галереи нет, только камера. На симуляторе камеры нет, поэтому кнопка там не появится, а проверять нужно на телефоне.
3. В проекте нет сложной схемы версий базы (VersionedSchema). Тогда новое необязательное поле `coverID` добавится к существующим книгам автоматически, у всех будет «нет обложки».
4. Удалённую обложку вернуть нельзя, поэтому перед удалением приложение спрашивает подтверждение.
5. `LibraryView` и `BookDetailView` — полные версии экранов. Если ваши экраны уже содержат что-то ещё, перенесите в них части про обложку: `CoverThumbnail` в строку, `CoverLarge` с кнопками на экран книги, удаление книги через `deleteBook`. Если книги удаляются ещё где-то, этот код лучше вызывать и там. Если не вызвать, лишние файлы удалятся при следующем открытии библиотеки.

## Что проверить на телефоне

- Сфотографировать обложку: она появляется на экране книги и в списке.
- Переснять: новое фото заменяет старое везде.
- Удалить обложку, затем удалить книгу целиком.
- Запретить камеру в Настройках: появляется окно с кнопкой «Открыть Настройки».
- Быстро пролистать большую библиотеку: прокрутка плавная, обложки появляются.

Ниже готовый код: 6 файлов и одна строка в настройках проекта. Я его не компилировал и не запускал: здесь нет Xcode и вашего проекта. Первая сборка в Xcode может показать мелкие ошибки компилятора, их легко поправить.

## Как это работает

1. На экране книги есть кнопка «Сфотографировать обложку». Открывается системная камера с привычными «Переснять» и «Использовать фото».
2. Фото уменьшается в фоне, интерфейс не подвисает. Сохраняются две копии: большая для экрана книги и маленькая для списка.
3. В библиотеке у каждой книги слева маленькая обложка. У книг без фото показывается серая заглушка со значком книги.
4. Обложку можно переснять или удалить. Перед удалением приложение спрашивает подтверждение.

